import { cn } from "@/lib/utils";
import type * as React from "react";

/**
 * Card (card)
 *
 * A bordered surface that groups related content, with header, title, description, action, content, and footer slots.
 *
 * Exports: Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle
 *
 * Props:
 * - Card: React.ComponentProps<"div">
 * - CardHeader: React.ComponentProps<"div">
 * - CardTitle: React.ComponentProps<"div">
 * - CardDescription: React.ComponentProps<"div">
 * - CardAction: React.ComponentProps<"div">
 * - CardContent: React.ComponentProps<"div">
 * - CardFooter: React.ComponentProps<"div">
 *
 * Theme tokens (shadcn names, from your theme): --card, --card-foreground, --muted-foreground, --radius, --radius-xl.
 *
 * Accessibility:
 * - Every slot renders a div with no implicit role.
 * - CardTitle is not a heading; put a heading element inside it when the title belongs in the document outline.
 * - Give icon-only buttons in CardAction an aria-label.
 *
 * Customize:
 * - Compose CardHeader, CardTitle, CardDescription, CardAction, CardContent, and CardFooter; CardAction moves to the top-right corner when present.
 * - Add border-b to CardHeader or border-t to CardFooter for divided sections; the padding adjusts automatically.
 * - The surface uses --card and --card-foreground.
 */

function Card({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "flex flex-col gap-6 rounded-xl border bg-card py-6 text-card-foreground shadow-sm",
        className
      )}
      data-slot="card"
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-2 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6",
        className
      )}
      data-slot="card-header"
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("font-semibold leading-none", className)}
      data-slot="card-title"
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("text-muted-foreground text-sm", className)}
      data-slot="card-description"
      {...props}
    />
  );
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "col-start-2 row-span-2 row-start-1 self-start justify-self-end",
        className
      )}
      data-slot="card-action"
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("px-6", className)}
      data-slot="card-content"
      {...props}
    />
  );
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("flex items-center px-6 [.border-t]:pt-6", className)}
      data-slot="card-footer"
      {...props}
    />
  );
}

export {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
};
